/* NULL when var_index is out of range or has no exported model. */
static const Tr2ModelEntry *tr2_model_entry(int var_index) {
    if (var_index < 0 || var_index >= TR2_MODEL_COUNT) return NULL;
    if (TR2_MODEL_TABLE[var_index].obj_path == NULL) return NULL;
    return &TR2_MODEL_TABLE[var_index];
}

